templates.template:
/* =============================================================================
   Breeze — a XenForo 2.3 port of the ProBoards skin by Silent of IncrediBAD.
   Blue-to-black page, the sparkling "breeze" banner with the menu along its lower edge,
   a white framed column, blue title bars, soft grey rows and glossy orb forum icons.
   The skin's images are embedded below, so the style needs no uploads.
   ============================================================================= */

@br-blue: #006bd0;
@br-titlebg: linear-gradient(180deg, #5ea2e1 0%, #3c8edb 30%, #1d7cd5 55%, #006bd0 60%, #006bd0 100%);
@br-border: #d3d3d3;

html
{
	background: url("data:image/jpeg;base64,") left top repeat-x #000;
}

body,
.p-pageWrapper
{
	background: transparent;
}

// ---- The framed 900px column -------------------------------------------------------

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 900px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body
{
	background: transparent;
	border: none;
}

.p-header-content
{
	height: 190px;
	padding: 0;
	background: url("data:image/webp;base64,") center top / 900px 190px no-repeat;
}

// The banner replaces the logo. Delete this rule to show the logo from Style properties.
.p-header-logo
{
	display: none;
}

.p-navSticky,
.p-navSticky.is-sticky
{
	position: static !important;
}

// Menu sits on the bottom of the banner, then the white box's rounded top edge
.p-nav
{
	position: relative;
	margin-top: -30px;
	color: #1a1a1a;
}

.p-nav-inner
{
	padding: 0 15px 27px;
	background: url("data:image/png;base64,") center bottom / 900px 27px no-repeat;
}

.p-nav-list
{
	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		font-family: 'Comfortaa', 'Varela Round', 'Arial Rounded MT Bold', 'Trebuchet MS', sans-serif;
		font-size: 17px;
		line-height: 20px;
		padding: 2px 14px;
		color: #1a1a1a;
		text-transform: lowercase;
		text-shadow: 0 0 3px #fff, 0 0 6px #fff;

		&:hover
		{
			color: #000;
			text-decoration: none;
			text-shadow: 0 0 4px #fff, 0 0 10px #bfe4ff;
		}
	}

	.p-navEl.is-selected
	{
		background: transparent;

		.p-navEl-link
		{
			color: #000;
			text-decoration: underline;
			text-decoration-color: rgba(255, 255, 255, .7);
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #fff;

	&:hover
	{
		background: rgba(255, 255, 255, .15);
		color: #fff;
		text-decoration: none;
	}
}

.p-sectionLinks-inner,
.p-body-inner
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA4QAAAAKCAYAAADsHJAOAAAAgUlEQVR42u3XMQ3CAABE0Q8GkIACJJB0qxT2CumOlG5NkIACJKCgTCRYaHhvve22f9i2rV/Tsp6qc3WprvM43AIAAGCXpmW9V4/qWb3mcXh/t6N7AAAA/pMgBAAAEIQAAAAIQgAAAAQhAAAAghAAAABBCAAAgCAEAABAEAIAALAfH64/DhFd8XS7AAAAAElFTkSuQmCC") center top / 900px 10px repeat-y;
	padding-left: 30px;
	padding-right: 30px;
}

.p-sectionLinks-inner a
{
	color: @br-blue;
}

.p-body-inner
{
	color: #000;
	padding-bottom: 20px;
}

// ---- Blocks: blue title bars, grey gradient rows, thin silver borders --------------------

.block-container
{
	background: #dfdfdf;
	border: 1px solid @br-border;
	border-radius: 0;
}

.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: @br-titlebg;
	border-bottom: 1px solid @br-border;
	color: #fff;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #fff;
	}

	.block-desc
	{
		color: rgba(255, 255, 255, .85);
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: rgba(255, 255, 255, .75);

	&:hover,
	&.is-active
	{
		color: #fff;
		border-color: #fff;
	}
}

.block-footer
{
	background: @br-titlebg;
	border-top-color: @br-border;
	color: #fff;

	a
	{
		color: #fff;
	}
}

.node + .node
{
	border-top: 1px solid @br-border;
}

.node-body,
.structItem
{
	background: linear-gradient(180deg, #fff 0, #dfdfdf 14px) #dfdfdf;
}

.structItem
{
	border-top-color: @br-border;
}

.node-title a
{
	color: @br-blue;
	font-weight: 700;
}

// Glossy orbs: blue when there are new posts, grey when read.
.node--forum .node-icon i
{
	display: block;
	width: 32px;
	height: 35px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / 32px 35px no-repeat;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	background-image: url("data:image/png;base64,");
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: @br-blue;
	}
}

.message,
.message-cell--user
{
	border-color: @br-border;
}

.message-cell--user
{
	background: linear-gradient(180deg, #fff 0, #dfdfdf 14px) #dfdfdf;
}

.button.button--primary,
a.button.button--primary
{
	background: @br-titlebg;
	border: 1px solid #00529f;
	color: #fff;

	&:hover
	{
		background: linear-gradient(180deg, #74b2ea 0%, #4f9ae2 30%, #2d88de 55%, #1279da 60%, #1279da 100%);
		color: #fff;
	}
}

// ---- Footer: the white box's base with the skin credit -----------------------------------

.p-footer
{
	background: transparent;
	color: #9a9a9a;

	&::before
	{
		content: '';
		display: block;
		max-width: 900px;
		height: 43px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 900px 43px no-repeat;
	}

	a
	{
		color: #3d9cf0;

		&:hover
		{
			color: #8cc6ff;
		}
	}
}

.p-footer-copyright::after
{
	content: "Breeze skin created by Silent of IncrediBAD";
	display: block;
	margin-top: 4px;
	color: #3d9cf0;
}

// ---- Narrower than the 900px frame -------------------------------------------------

@media (max-width: 919px)
{
	.p-header-content
	{
		height: auto;
		aspect-ratio: 900 / 190;
		background-size: 100% auto;
	}

	.p-nav
	{
		margin-top: 0;
	}

	.p-nav-inner
	{
		padding: 0 10px;
		background: @br-titlebg;
	}

	.p-nav-list .p-navEl-link
	{
		color: #fff;
		text-shadow: none;
	}

	.p-sectionLinks-inner,
	.p-body-inner
	{
		background: #fff;
		padding-left: 10px;
		padding-right: 10px;
	}

	.p-footer::before
	{
		background-size: 100% 43px;
	}
}
